import manifest from "./coverManifest.json";

/**
 * Covers of the home monitor and of the blog cards: one per production, plus an
 * `_en` entry where the cover has an English version. The keys are the release ids.
 *
 * Each path is the full-size original in /public. Visitors do not download it: every
 * cover has a light AVIF twin (about an eighth of the weight) generated by
 * `npm run covers` and listed in coverManifest.json. The page loads the twin and
 * switches to the original only if the twin fails to load, as it does in a browser
 * without AVIF. The build fails when a cover listed here has no up-to-date twin
 * (see scripts/build-covers.mjs).
 *
 * New episode: add its cover here, run `npm run covers`, use COVERS.<id> as the
 * `thumb` of its monitor channel and of its blog card, and commit the .avif.
 */
export const COVERS = {
  ep12: "/brand/thumbs/ep12/R06_arena_t15.png",
  ep11: "/brand/thumbs/ep11/R01_hydrogen_t15.png",
  ep10: "/brand/thumbs/ep10/R05_arena_mid.png",
  ep09: "/brand/thumbs/ep09/P01_fable52_t10.png",
  ep08: "/brand/thumbs/ep08/P03_carbon_recuperacion_t10.png",
  ep07: "/news/omni12/thumb_A.jpg",
  ep07_en: "/news/omni12/thumb_A_en.jpg",
  ep06: "/brand/thumbs/ep06/05-hexagone-piso-cae-3d_arena.png",
  ep05: "/brand/thumbs/ep05/01-impacto-planetario-3d_argon.png",
  cc02: "/brand/thumbs/cc02_thumb_A.png",
  carbon01: "/brand/thumbs/carbon_thumb_A.jpg",
  carbon01_en: "/brand/thumbs/carbon_thumb_A_en.jpg",
  ep04: "/brand/thumbs/ep04_thumb_A.jpg",
  ep03: "/brand/thumbs/ep03_thumb_A.jpg",
  cc01: "/brand/thumbs/cc01_thumb_A.jpg",
  ep02: "/brand/thumbs/ep02_thumb_A_1280.jpg",
  ep01: "/brand/thumbs/01_marcador-0-10_1280.jpg",
} as const;

const LIGHT_TWINS: Partial<Record<string, { avif: string }>> = manifest.covers;

/**
 * The light AVIF twin of a cover, or undefined when it has none. Without a twin the
 * page loads the original, which works but is heavy; the e2e suite fails on any
 * cover over its weight budget (e2e/home-covers.spec.ts).
 */
export function lightCover(original: string): string | undefined {
  return LIGHT_TWINS[original]?.avif;
}
